css:
:scope { width: min(100%, 630px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 1 / span 24; grid-row: 1 / span 22; font-family: var(--os-font-heading); font-size: 88px; font-weight: 380; line-height: 1; letter-spacing: -0.025em; color: var(--os-color-text); }
.gx__i2 { grid-column: 1 / span 19; grid-row: 26 / span 13; font-family: var(--os-font-label); font-size: 22.4px; font-weight: 400; line-height: 1.5; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i3 { grid-column: 1 / span 9; grid-row: 42 / span 6; font-family: var(--os-font-label); font-size: 16.3px; font-weight: 700; line-height: 1.1; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i4 { grid-column: 10 / span 5; grid-row: 42 / span 6; font-family: var(--os-font-label); font-size: 16.3px; font-weight: 700; line-height: 1.1; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i5 { grid-column: 1 / span 16; grid-row: 50 / span 7; font-family: var(--os-font-label); font-size: 16.3px; font-weight: 400; line-height: 1.65; letter-spacing: 0em; color: inherit; }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i1 { font-family: var(--os-font-heading); font-size: 70px; }
  .gx__i2 { font-family: var(--os-font-label); font-size: 18px; }
  .gx__i3 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i4 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i5 { font-family: var(--os-font-label); font-size: 14px; }
}
